  "codex.locked": "Закрыто хардкором",
  "codex.lockedTiles": "Идёт хардкорный забег: справочник закрыт, чтобы нельзя было подсмотреть, на чём играют игроки и кто с кем был в составе. Откроется, когда забег закончится.",
  "codex.lockedHeroes": "Идёт хардкорный забег: профили игроков закрыты, чтобы нельзя было подсмотреть, на чём они играют. Общий список героев остаётся доступен.",
