  "arcade.sig.souls.desc": "Каждое убийство даёт душу (элита — 6): +1.2 урона за душу, до 36.",
  "arcade.sig.swipes": "Ярость",
  "arcade.sig.swipes.desc": "Удары по одной цели подряд копят ярость: +4 урона за стак, до 12.",
  "arcade.sig.cleave": "Рассечение",
  "arcade.sig.cleave.desc": "Каждый удар задевает врагов рядом с целью на 50% урона.",
