  "rules.tile": "Game mode rules",
  "rules.tileHint": "What the modes are, how they work and what matters",
  "rules.eyebrow": "HOW TO PLAY",
  "rules.title": "Game mode rules",
  "rules.intro": "Every mode shares one Dota scene and one team-power score, but each applies its own pressure: Classic asks how high you can jump in one attempt, Roguelite asks how long you can last, Manager asks what you can build on a budget.",
  "rules.scoreTitle": "What makes up team power",
  "rules.scoreLead": "The same score works in every mode — three terms, and only the first depends on raw ratings:",
  "rules.scoreMoral": "The moral is the same everywhere: five practiced teammates on familiar heroes beat a scatter of expensive lone stars.",
  "rules.classicTitle": "Classic · Quick Draft",
  "rules.classicStepPacks": "Packs",
  "rules.classicStepRoster": "Five + heroes",
  "rules.classicStepGroups": "Groups",
  "rules.classicStepPlayoffs": "Playoffs",
  "rules.classicStepPlace": "Placement",
  "rules.classicHow1": "Each pack is a pick of five: a player for an open role plus a hero. Team Packs keeps real rosters together, Mixed Draft frees up the roles.",
  "rules.classicHow2": "Rerolls are the difficulty: Hard lives without them, Easy rerolls packs without limits.",
  "rules.classicHow3": "Look beyond OVR: clicking a player opens their heroes and past teammates — synergy and chemistry are earned there.",
  "rules.classicHow4": "The result is a placement among 18 teams. The run joins your career history, and the seed link gives a friend the same packs.",
  "rules.runTitle": "Roguelite Run",
  "rules.runDiagramThreshold": "Target placement",
  "rules.runDiagramPower": "Strength without upgrades",
  "rules.runDiagramBoss": "Act boss",
  "rules.runDiagramCamp": "Bootcamp between stages",
  "rules.runDiagramActs": "25 stages · 5 acts",
  "rules.runHow1": "A season is 5 acts of 5 stages. The target placement rises faster than your raw strength: without upgrades the run ends in act one.",
  "rules.runHow2": "Between stages comes the Bootcamp: a reward, a market of players and heroes, items and tactics. Gold is the only resource, and savings earn interest.",
  "rules.runHow3": "Each act's finale is guarded by a boss with its own condition. The rule is visible in advance and countered by your build; scouting reveals the next one.",
  "rules.runHow4": "Winning the season opens the Dynasty — voluntary loops against a growing field. Cheat Mode stays a sandbox outside the records.",
  "rules.managerTitle": "Esports Manager",
  "rules.managerStepTryouts": "Tryouts",
  "rules.managerStepContracts": "Contracts",
  "rules.managerStepSeason": "Season",
  "rules.managerStepFinale": "Finale",
  "rules.managerStepOffseason": "Off-season",
  "rules.managerHow1": "Five stars are unaffordable by design: tryout salaries are hidden ($ bands), and you cannot sign a roster above your monthly income — offseason renewals included: going over budget forces a release.",
  "rules.managerHow2": "Practiced pairs are the big discount: Chemistry grants power for free, while one expensive star eats the budget of two roles.",
  "rules.managerHow3": "A season is five cycles: two tier-2s are guaranteed, but the online and LAN events with real prize money open only through the qualifier (top-2).",
  "rules.managerHow4": "The season ends at the Aegis Championship via a top-1 qualifier. In the off-season form drifts, contracts renew, and weak links can be released.",
  "rules.tournamentTitle": "Real Tournament",
  "rules.tournamentStepEvent": "Event",
  "rules.tournamentStepLock": "Roster lock",
  "rules.tournamentStepDraft": "Challenger draft",
  "rules.tournamentStepSim": "Field simulation",
  "rules.tournamentStepPlace": "Finish among the field",
  "rules.tournamentHow1": "Pick a real tournament — its 17 strongest rosters become the field, as they played at the event.",
  "rules.tournamentHow2": "Every event player is locked out of your draft and market — build your five from the rest of the scene, any era.",
  "rules.tournamentHow3": "Everyone is rated by their own era's form: a legend arrives with their rating from back then, not re-scaled to today.",
  "rules.tournamentHow4": "The seed decides the outcome: real results are not replayed — it is a simulation against a real field, and the link reproduces the run.",
  "rules.arenaTitle": "Arena",
  "rules.arenaStepRoom": "Room of 18",
  "rules.arenaStepPlayers": "Players ×5",
  "rules.arenaStepHeroes": "Heroes ×5",
  "rules.arenaStepSim": "One tournament",
  "rules.arenaStepPlace": "Placement",
  "rules.arenaHow1": "One pool for everyone: a taken player or hero disappears for the whole room at once — buying out all the stars is impossible by construction.",
  "rules.arenaHow2": "Everyone picks simultaneously: a pick plus an optional backup. Conflicts go to the better round priority; the snake inverts every round.",
  "rules.arenaHow3": "Bots play for the silent and fill the field up to 18; a round resolves once the last human is in, or on the host's timer.",
  "rules.arenaHow4": "After the draft — one 18-team tournament on a shared seed: the whole room sees the same table, and what you drafted is what wins.",
  "rules.duelTitle": "Duel",
  "rules.duelStepRoom": "Room for two",
  "rules.duelStepPlayers": "Player snake",
  "rules.duelStepHeroes": "Bans & picks",
  "rules.duelStepGame": "Series game",
  "rules.duelStepSeries": "Bo1/3/5 score",
  "rules.duelHow1": "Both rosters come from a shared pool: a player taken by one captain is never offered to the other.",
  "rules.duelHow2": "Each game's hero pool is the combined repertoire of all ten players: a ban hits your opponent's comfort zone, not an abstract meta.",
  "rules.duelHow3": "The game is decided by the same ELO curve as every tournament; each move gets ~45 seconds, then an auto-move plays.",
  "rules.duelHow4": "After the series you can rematch in the same room: new seed, same rules, sides swap — the first pick goes to your opponent.",
  "rules.onlineNote": "Online mode: it needs the internet and the room server. In a build without the server, the card on the main screen stays locked.",
  "codex.back": "Back to settings",
  "codex.career": "Run history",
