  "codex.lockedHeroes": "A hardcore run is in progress: player profiles are locked so you cannot peek at what they play. The overall hero list stays available.",
  "codex.lockedTeammates": "A hardcore run is in progress: rosters and player pairs are locked. Come back after the run.",
  "hard.gateTitle": "Enable hardcore?",
  "hard.gateText": "The mode removes the hints you normally lean on while drafting. It only turns on deliberately.",
  "hard.rule1": "Player profiles are locked — you cannot check which heroes a player plays. Both in the draft and in the codex.",
  "hard.rule2": "No opponent reroll: the tournament field is drawn once.",
  "hard.rule3": "No pack rerolls: difficulty is locked to Hard, a dealt pack cannot be redrawn.",
  "hard.rule4": "The roster web is locked — no peeking at who played with whom during the run.",
  "hard.rule5": "The run is marked as hardcore in your history.",
  "hard.gateAck": "I understand these hints will be unavailable",
  "hard.gateConfirm": "Enable hardcore",
  "cheat.section": "Special rules",
  "cheat.title": "Cheat Mode",
  "cheat.off": "Off",
  "cheat.offHint": "Normal run economy",
  "cheat.on": "Unlimited gold",
  "cheat.onHint": "The run is excluded from stats",
  "cheat.gateTitle": "Enable Cheat Mode?",
  "cheat.gateText": "This run will have unlimited gold. Economic decisions will lose most of their meaning, so the run may quickly become less interesting.",
  "cheat.rule1": "The result will not count towards normal career statistics.",
  "cheat.rule2": "The run unlocks no achievements and no new difficulty levels.",
  "cheat.rule3": "Hardcore will be turned off: it cannot run alongside Cheat Mode.",
  "cheat.gateConfirm": "Enable Cheat Mode",
  "cheat.badge": "CHEAT MODE · ∞ GOLD",
