  "arcade.titleRiver": "The river and the Roshan pit",
  "arcade.leadRiver": "Runes live in the river, Roshan in the pit at the map's centre: he won't leave it and regenerates while you're outside, while the jungle doesn't wait. Enemies are 30% tougher.",
